static const char web_html[] =
"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>DoveOS Local Transfer</title><link rel=\"stylesheet\" href=\"style.css\"></head><body><main><header><span class=\"dove\">&#x1F54A;</span><div><h1>Local Transfer</h1><p>Send files to your dock or download them here.</p></div></header><section><h2>Send to dock</h2><label class=\"pick\">Choose files<input id=\"files\" type=\"file\" multiple></label><button id=\"send\" disabled>Send files</button><progress id=\"progress\" max=\"100\" value=\"0\" hidden></progress><p id=\"message\" role=\"status\">Choose one or more files. Existing files are kept.</p></section><section><div class=\"heading\"><h2>Files on dock</h2><button id=\"refresh\">Refresh</button></div><nav id=\"crumbs\"></nav><p id=\"empty\" hidden>No files in this folder yet.</p><ul id=\"listing\"></ul><p id=\"info\"></p></section><footer>Keep Local Transfer open on the dock. Both devices must be on the same local network. Files travel directly between your devices.</footer></main><script src=\"app.js\"></script></body></html>"
;
static const char web_css[] =
"*{box-sizing:border-box}body{margin:0;background:#e9eef1;color:#13252d;font:16px system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}main{max-width:760px;margin:32px auto;padding:0 18px}header{display:flex;gap:15px;align-items:center;margin-bottom:22px}.dove{font-size:40px}h1{font-size:27px;margin:0}h2{font-size:19px;margin:0 0 14px}p{line-height:1.5}header p{margin:6px 0;color:#49606b}section{background:white;border:1px solid #cdd9df;border-radius:12px;padding:22px;margin:16px 0}button,.pick{font:inherit;border:1px solid #597887;background:#f3f7f8;color:#15384a;border-radius:6px;padding:10px 15px;cursor:pointer;display:inline-block}button:hover,.pick:hover{background:#e7f0f4}button:disabled{opacity:.5;cursor:default}input[type=file]{display:block;max-width:100%;margin-top:10px}.pick{display:block;background:transparent;border-style:dashed;margin-bottom:12px}progress{display:block;width:100%;height:18px;margin-top:16px}progress[hidden]{display:none}.heading{display:flex;justify-content:space-between;align-items:center;gap:12px}nav{margin:12px 0;overflow-wrap:anywhere}nav button{border:0;background:none;padding:5px;color:#075a8b}ul{list-style:none;padding:0;margin:0}li{border-top:1px solid #e1e9ed;display:flex;gap:12px;align-items:center;padding:14px 0;min-width:0}li span{flex:1;overflow-wrap:anywhere}li small{display:block;color:#5d737d;margin-top:4px}li a{color:#075a8b;text-decoration:none;padding:7px;font-weight:600}li button{flex:1;text-align:left;border:0;background:none;padding:0;overflow-wrap:anywhere}#message,#info{color:#49606b;margin-bottom:0}footer{font-size:13px;color:#5a707b;line-height:1.6;margin:22px 0} @media(max-width:500px){main{margin:20px auto}section{padding:17px}h1{font-size:24px}li{gap:6px}}"
;
static const char web_js[] =
"\"use strict\";\n"
"const base=new URL(\"./\",location.href);let folder=\"\",busy=false;\n"
"const $=id=>document.getElementById(id),size=n=>n<1024?n+\" B\":n<1048576?(n/1024).toFixed(1)+\" KB\":n<1073741824?(n/1048576).toFixed(1)+\" MB\":(n/1073741824).toFixed(2)+\" GB\";\n"
"const api=(name,args)=>{const u=new URL(\"api/\"+name,base);for(const k in args)u.searchParams.set(k,args[k]);return u;};\n"
"async function list(){try{const r=await fetch(api(\"list\",{path:folder}),{cache:\"no-store\"});if(!r.ok)throw Error(await r.text());const data=await r.json();$(\"listing\").replaceChildren();$(\"crumbs\").replaceChildren();const parts=folder.split(\"/\").filter(Boolean);[\"Shared folder\",...parts].forEach((name,i)=>{const b=document.createElement(\"button\");b.textContent=name+(i<parts.length?\" /\":\"\");b.onclick=()=>{folder=parts.slice(0,i).join(\"/\");list();};$(\"crumbs\").appendChild(b);});for(const f of data.files){const row=document.createElement(\"li\"),text=document.createElement(f.directory?\"button\":\"span\");text.textContent=(f.directory?\"\\uD83D\\uDCC1 \":\"\\uD83D\\uDCC4 \")+f.name;if(f.directory){text.onclick=()=>{folder=[folder,f.name].filter(Boolean).join(\"/\");list();};}else{const small=document.createElement(\"small\");small.textContent=size(f.size);text.appendChild(small);}row.appendChild(text);if(!f.directory){const a=document.createElement(\"a\");a.textContent=\"Download\";a.href=api(\"download\",{path:[folder,f.name].filter(Boolean).join(\"/\")});a.download=f.name;row.appendChild(a);}$(\"listing\").appendChild(row);}$(\"empty\").hidden=data.files.length!==0;$(\"info\").textContent=data.truncated?\"Showing the first 2,000 items. Open a smaller folder to see more.\":data.files.length+\" items\";}catch(e){$(\"info\").textContent=\"Cannot connect. Check that Local Transfer is open on the dock. \"+e.message;}}\n"
"$(\"files\").onchange=()=>{$(\"send\").disabled=busy||!$(\"files\").files.length;};$(\"refresh\").onclick=list;\n"
"function upload(file){return new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open(\"PUT\",api(\"upload\",{dir:folder,name:file.name}));x.setRequestHeader(\"Content-Type\",\"application/octet-stream\");x.upload.onprogress=e=>{if(e.lengthComputable)$(\"progress\").value=e.loaded/e.total*100;};x.onload=()=>x.status===201?resolve():reject(Error(x.responseText||\"Transfer failed (\"+x.status+\")\"));x.onerror=()=>reject(Error(\"Connection lost. Check the dock and try again.\"));x.onabort=()=>reject(Error(\"Transfer cancelled.\"));x.send(file);});}\n"
"$(\"send\").onclick=async()=>{busy=true;$(\"send\").disabled=true;$(\"files\").disabled=true;$(\"progress\").hidden=false;let good=0,errors=[];for(const file of $(\"files\").files){$(\"message\").textContent=\"Sending \"+file.name+\"...\";$(\"progress\").value=0;try{await upload(file);good++;}catch(e){errors.push(file.name+\": \"+e.message);}}$(\"progress\").hidden=true;$(\"message\").textContent=good+\" file(s) saved to the dock.\"+(errors.length?\" \"+errors.join(\"; \"):\"\");busy=false;$(\"files\").disabled=false;$(\"send\").disabled=!$(\"files\").files.length;list();};list();\n"
;
